def normalize_relationship(value):
    return str(value).strip().lower().replace("-", "").replace("_", "").replace(" ", "").rstrip("s")

eligible_relationships = {"friend", "coworker"}
eligible_contacts = [
    contact for contact in all_contacts
    if any(normalize_relationship(relationship) in eligible_relationships for relationship in contact["relationships"])
]
eligible_contact_emails = {
    str(contact["email"]).strip().lower() for contact in eligible_contacts
}
print({"eligible_contact_count": len(eligible_contacts), "eligible_email_count": len(eligible_contact_emails)})
